CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), cognito_sub text UNIQUE, name text NOT NULL, email text UNIQUE NOT NULL, password_hash text, role text NOT NULL DEFAULT 'MEMBER' CHECK(role IN ('ADMIN','PASTOR','STAFF','MEMBER')), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')), last_login timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ministries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, description text NOT NULL DEFAULT '', leader_id uuid, meeting_schedule text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE members(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE REFERENCES users(id), first_name text NOT NULL, last_name text NOT NULL, email text, phone text, date_of_birth date, gender text, address text, emergency_contact text, membership_date date NOT NULL DEFAULT current_date, ministry_id uuid REFERENCES ministries(id), profile_photo text, qr_token text NOT NULL UNIQUE DEFAULT encode(gen_random_bytes(32),'hex'), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
ALTER TABLE ministries ADD CONSTRAINT ministry_leader_fk FOREIGN KEY(leader_id) REFERENCES members(id);
CREATE TABLE services(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, description text NOT NULL DEFAULT '', date date NOT NULL, start_time time NOT NULL, end_time time, location text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','completed','cancelled')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE attendance(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), member_id uuid NOT NULL REFERENCES members(id), service_id uuid NOT NULL REFERENCES services(id), status text NOT NULL DEFAULT 'present' CHECK(status IN ('present','absent','excused')), check_in_time timestamptz NOT NULL DEFAULT now(), check_out_time timestamptz, attendance_method text NOT NULL CHECK(attendance_method IN ('QR_SCAN','MANUAL','ADMIN')), created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(member_id,service_id));
CREATE TABLE events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, description text NOT NULL DEFAULT '', date date NOT NULL, start_time time NOT NULL, end_time time, location text NOT NULL DEFAULT '', maximum_capacity integer CHECK(maximum_capacity>0), registration_required boolean NOT NULL DEFAULT false, image text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE event_registrations(event_id uuid REFERENCES events(id), user_id uuid REFERENCES users(id), created_at timestamptz DEFAULT now(), PRIMARY KEY(event_id,user_id));
CREATE TABLE settings(id integer PRIMARY KEY CHECK(id=1), data jsonb NOT NULL);
INSERT INTO settings VALUES(1,'{"church_name":"Grace Community Church","mission":"Growing in faith. Serving our neighbours.","vision":"A welcoming community where everyone belongs.","values":"Faith, compassion, integrity and service","address":"Configure your church address","email":"office@example.org","phone":"Configure your phone","social_links":[],"service_times":[{"name":"Sunday Worship","time":"9:00 AM – 11:00 AM"},{"name":"Wednesday Bible Study","time":"6:00 PM – 8:00 PM"},{"name":"Friday Prayer","time":"7:00 PM – 9:00 PM"}]}');
CREATE TABLE contact_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL, message text NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE audit_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id), action text NOT NULL, resource text NOT NULL, resource_id uuid, created_at timestamptz DEFAULT now());
CREATE INDEX members_last_name_idx ON members(lower(last_name));
CREATE INDEX members_status_idx ON members(status) WHERE deleted_at IS NULL;
CREATE INDEX members_ministry_idx ON members(ministry_id);
CREATE INDEX attendance_member_idx ON attendance(member_id);
CREATE INDEX attendance_service_idx ON attendance(service_id);
CREATE INDEX services_date_idx ON services(date);
CREATE INDEX events_date_idx ON events(date);
CREATE FUNCTION touch_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN NEW.updated_at=now(); RETURN NEW; END$$;
CREATE TRIGGER users_touch BEFORE UPDATE ON users FOR EACH ROW EXECUTE FUNCTION touch_updated_at();
CREATE TRIGGER members_touch BEFORE UPDATE ON members FOR EACH ROW EXECUTE FUNCTION touch_updated_at();
CREATE TRIGGER attendance_touch BEFORE UPDATE ON attendance FOR EACH ROW EXECUTE FUNCTION touch_updated_at();
CREATE TRIGGER services_touch BEFORE UPDATE ON services FOR EACH ROW EXECUTE FUNCTION touch_updated_at();
CREATE TRIGGER events_touch BEFORE UPDATE ON events FOR EACH ROW EXECUTE FUNCTION touch_updated_at();
CREATE TRIGGER ministries_touch BEFORE UPDATE ON ministries FOR EACH ROW EXECUTE FUNCTION touch_updated_at();
